    // Validate input
    if (value == null) {
        throw new IllegalArgumentException("Type value cannot be null");
    }
    String trimmed = value.trim();
    if (trimmed.isEmpty()) {
        throw new IllegalArgumentException("Type value cannot be empty or whitespace");
    }

    // Ensure the type table exists
    if (typeTable == null) {
        typeTable = new java.util.ArrayList<>();
    }

    // Search for an existing type
    for (int i = 0; i < typeTable.size(); i++) {
        TypeSymbol ts = typeTable.get(i);
        if (ts != null && trimmed.equals(ts.getName())) {
            return i; // existing type found
        }
    }

    // Add new type
