    }
}

@Override
public void accept(final METRICS data) {
    if (data == null) {
        return;
    }
    // Ensure the cache exists; if not, nothing to do
    if (cache == null) {
        return;
    }
    try {
        METRICS existing = cache.get(data);
        if (existing != null) {
            METRICS merged;
            try {
                // Attempt to merge the new data with the existing value
                merged = data.merge(existing);
            } catch (Exception e) {
                // If merge fails, fall back to the existing value
                merged = existing;
            }
            cache.put(data, merged);
        } else {
            // No existing entry, simply store the new data
            cache.put(data, data);
        }
    } catch (Exception e) {
        // Silently ignore any unexpected runtime issues
    }
}

void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }
    // If already before the bucket, nothing to do
    if (this.next == bucket || bucket.prev == this) {
        return;
    }
    // Detach this from its current neighbors
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }
    // Insert this before the bucket
    this.prev = bucket.prev;
    this.next = bucket;
    if (bucket.prev != null) {
        bucket.prev.next = this;
    }
    bucket.prev = this;
}

