        java.util.Map<String, Object> historyProps = mappings.getProperties();
        java.util.Map<String, Object> diff = new java.util.LinkedHashMap<>();
        for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String key = entry.getKey();
            if ("_source".equals(key)) {
                continue;
            }
            if (!historyProps.containsKey(key)) {
                diff.put(key, entry.getValue());
            }
        }
        return new Mappings(diff);
    } catch (Exception e) {
        // In case of any error, return an empty mapping to avoid breaking the caller
        return new Mappings();
    }
}

