}

public long readLong(final int offset){
    // Validate offset to avoid ArrayIndexOutOfBoundsException
    if (offset < 0 || offset + 8 > this.b.length) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }
    final byte[] b = this.b;
    return ((long) b[offset] << 56) |
           ((long) (b[offset + 1] & 0xFF) << 48) |
           ((long) (b[offset + 2] & 0xFF) << 40) |
           ((long) (b[offset + 3] & 0xFF) << 32) |
           ((long) (b[offset + 4] & 0xFF) << 24) |
           ((long) (b[offset + 5] & 0xFF) << 16) |
           ((long) (b[offset + 6] & 0xFF) << 8) |
           ((long) (b[offset + 7] & 0xFF));
}

public boolean equals(final byte[] data, int offset, final int len) {
    // Validate input array
    if (data == null) {
        return false;
    }
    if (offset < 0 || len < 0) {
        return false;
    }
    // Prevent integer overflow when computing offset + len
    if (offset > data.length - len) {
        return false;
    }

    // If internal array is null, only match when len is zero
    if (this.data == null) {
        return len == 0;
    }

    // Lengths must match
    if (this.data.length != len) {
        return false;
    }

    // Compare byte by byte
    for (int i = 0; i < len; i++) {
        if (this.data[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

