protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    if (start >= end) {
        return ranges;
    }
    long s = start;
    while (s < end) {
        long e;
        if (s > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            e = end;
        } else {
            e = Math.min(end, s + FETCH_DATA_DURATION);
        }
        ranges.add(new TimeRange(s, e));
        s = e;
    }
    return ranges;
}

