static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }

    long bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + bucketDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index=" + index + ", len=" + len + ", str.length()=" + str.length());
    }
    long size = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char low = str.charAt(i + 1);
            if (Character.isLowSurrogate(low)) {
                codePoint = Character.toCodePoint(ch, low);
                i += 2;
            } else {
                // Lone high surrogate, treat as 3 bytes
                codePoint = ch;
                i++;
            }
        } else {
            codePoint = ch;
            i++;
        }

        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }

        if (size > Integer.MAX_VALUE) {
            throw new ArithmeticException("UTF-8 size exceeds Integer.MAX_VALUE");
        }
    }
    return (int) size;
}

