    // No bytes to add
    if (byteLength <= 0) {
        return this;
    }

    // If the source array is null, we just add nullbytes (zeros)
    if (byteArrayValue == null) {
        ensureCapacity(length + byteLength);
        for (int i = 0; i < byteLength; i++) {
            buffer[length + i] = 0;
        }
        length += byteLength;
        return this;
    }

    // Validate offset and length against the source array bounds
    if (byteOffset < 0 || byteLength < 0 || byteOffset > byteArrayValue.length - byteLength) {
        throw new IndexOutOfBoundsException(
            "byteOffset (" + byteOffset + ") and byteLength (" + byteLength + ") are out of bounds for array of length " + byteArrayValue.length);
    }

    // Ensure there is enough space in the vector
    ensureCapacity(length + byteLength);

    // Copy the requested bytes into the vector
    System.arraycopy(byteArrayValue, byteOffset, buffer, length, byteLength);
    length += byteLength;
    return this;
}

