public void removeFromTreeEdgeList() {
    // Remove this edge from the first doubly linked list of tree edges
    if (treeEdgePrev != null) {
        treeEdgePrev.treeEdgeNext = treeEdgeNext;
    }
    if (treeEdgeNext != null) {
        treeEdgeNext.treeEdgePrev = treeEdgePrev;
    }

    // Remove this edge from the second doubly linked list of tree edges
    if (treeEdgePrev2 != null) {
        treeEdgePrev2.treeEdgeNext2 = treeEdgeNext2;
    }
    if (treeEdgeNext2 != null) {
        treeEdgeNext2.treeEdgePrev2 = treeEdgePrev2;
    }

    // Nullify all pointers to help garbage collection and avoid accidental reuse
    treeEdgePrev = null;
    treeEdgeNext = null;
    treeEdgePrev2 = null;
    treeEdgeNext2 = null;
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Pattern to find ${var} placeholders
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
    int maxDepth = 10; // prevent infinite recursion
    String result = value;
    for (int depth = 0; depth < maxDepth; depth++) {
        java.util.regex.Matcher matcher = pattern.matcher(result);
        boolean found = false;
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            found = true;
            String varName = matcher.group(1);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
                // leave placeholder unchanged if no property found
                matcher.appendReplacement(sb, Matcher.quoteReplacement(matcher.group(0)));
            } else {
                matcher.appendReplacement(sb, Matcher.quoteReplacement(varValue));
            }
        }
        matcher.appendTail(sb);
        result = sb.toString();
        if (!found) {
            break; // no more placeholders
        }
    }
    return result;
}

