private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null but not both, no match
    if (str == null || suffix == null) {
        return false;
    }
    // If suffix is longer than str, cannot match
    if (suffix.length() > str.length()) {
        return false;
    }
    // Use regionMatches to compare the end of the string with the suffix
    int start = str.length() - suffix.length();
    return str.regionMatches(ignoreCase, start, suffix, 0, suffix.length());
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new NullPointerException("URI is null");
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    // Remove leading slash if present (absolute path component)
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    // Split on '/' and keep empty segments
    String[] parts = path.split("/", -1);
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>(parts.length);
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 should always be supported
                throw new IllegalArgumentException("UTF-8 encoding not supported", e);
            } catch (IllegalArgumentException e) {
                // Invalid percent-encoding
                throw new IllegalArgumentException("Invalid percent-encoding in segment: " + part, e);
            }
        }
        result.add(new PathSegmentImpl(seg));
    }
    return result;
}

