public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();
    if (minX > maxX) {
        throw new IllegalArgumentException("Invalid box: minX > maxX");
    }
    if (minY > maxY) {
        throw new IllegalArgumentException("Invalid box: minY > maxY");
    }
    double midX = (minX + maxX) / 2.0;
    Box2D left = new Box2D(minX, minY, midX, maxY);
    Box2D right = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(left, right);
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    if (this.bytes == null) {
        this.bytes = new byte[size];
        return;
    }
    int currentSize = this.size;
    int currentCapacity = this.bytes.length;
    int required = currentSize + size;
    if (required <= currentCapacity) {
        return;
    }
    int newCapacity = Math.max(currentCapacity * 2, required);
    if (newCapacity < 0) { // handle integer overflow
        newCapacity = Integer.MAX_VALUE;
    }
    byte[] newBytes = new byte[newCapacity];
    System.arraycopy(this.bytes, 0, newBytes, 0, currentSize);
    this.bytes = newBytes;
}

