public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();
        // Timestamp
        long ts = event.getTimeStamp();
        String time = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                .format(new java.util.Date(ts));
        sb.append(time).append(" ");
        // Level
        Object levelObj = event.getLevel();
        sb.append((levelObj != null) ? levelObj.toString() : "UNKNOWN").append(" ");
        // Thread
        String thread = event.getThreadName();
        sb.append("[")
          .append((thread != null) ? thread : "UNKNOWN")
          .append("] ");
        // Logger
        String logger = event.getLoggerName();
        sb.append((logger != null) ? logger : "UNKNOWN")
          .append(" - ");
        // Message
        Object msgObj = event.getMessage();
        sb.append((msgObj != null) ? msgObj.toString() : "null");
        // Throwable
        if (event.getThrowableInformation() != null) {
            java.lang.Throwable t = event.getThrowableInformation().getThrowable();
            if (t != null) {
                sb.append(System.lineSeparator());
                sb.append(t.toString());
                for (StackTraceElement ste : t.getStackTrace()) {
                    sb.append(System.lineSeparator())
                      .append("\tat ")
                      .append(ste.toString());
                }
            }
        }
        return sb.toString();
    } catch (Exception e) {
        // Fallback: return the message or empty string
        Object msgObj = event.getMessage();
        return (msgObj != null) ? msgObj.toString() : "";
    }
}

