private void putAbstractTypes(final int start, final int end) {
    // Validate indices
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices");
    }
    // Estimate required space: at most two entries per type
    int required = (end - start) * 2;
    if (stackMapTableEntriesCount + required > stackMapTableEntries.length) {
        throw new IllegalStateException("Not enough space in stackMapTableEntries");
    }
    for (int i = start; i < end; ++i) {
        final int type = currentFrame[i];
        stackMapTableEntries[stackMapTableEntriesCount++] = type;
        // OBJECT (7) and UNINITIALIZED (8) types have an extra data word
        if (type == 7 || type == 8) {
            if (i + 1 >= currentFrame.length) {
                throw new IllegalStateException("Missing data for OBJECT/UNINITIALIZED type");
            }
            stackMapTableEntries[stackMapTableEntriesCount++] = currentFrame[++i];
        }
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new NullPointerException("InputStream cannot be null");
    }
    // Read all bytes from the input stream
    byte[] data;
    try {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] tmp = new byte[8192];
        int read;
        while ((read = in.read(tmp)) != -1) {
            baos.write(tmp, 0, read);
        }
        data = baos.toByteArray();
    } catch (IOException e) {
        // Propagate the exception
        throw e;
    }
    // Clear and fill the buffer
    this.buffer = data;
    // Reset the read pointer to the start
    this.readPointer = 0;
}

