public String toString(JSONWriter.Feature... features) {
    try {
        JSONWriter writer;
        if (features == null || features.length == 0) {
            writer = new JSONWriter();
        } else {
            // Filter out any null features
            int nonNullCount = 0;
            for (JSONWriter.Feature f : features) {
                if (f != null) {
                    nonNullCount++;
                }
            }
            if (nonNullCount == 0) {
                writer = new JSONWriter();
            } else {
                JSONWriter.Feature[] nonNullFeatures = new JSONWriter.Feature[nonNullCount];
                int idx = 0;
                for (JSONWriter.Feature f : features) {
                    if (f != null) {
                        nonNullFeatures[idx++] = f;
                    }
                }
                writer = new JSONWriter(nonNullFeatures);
            }
        }
        writer.writeObject(this);
        return writer.toString();
    } catch (Exception e) {
        throw new RuntimeException("Failed to serialize object to JSON", e);
    }
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return Character.valueOf(s.charAt(0));
        } else {
            throw new Exception("Cannot convert String of length " + s.length() + " to Character");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return Character.valueOf((char) intVal);
    }
    if (value instanceof Boolean) {
        // Optional: convert Boolean to 't' or 'f'
        return Character.valueOf(((Boolean) value) ? 't' : 'f');
    }
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

