private static int digitValue(final char c){
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if(jsonObject == null){
        return result;
    }
    try{
        // Handle the special "ats" field if present
        if(jsonObject.has("ats")){
            JsonElement atsElem = jsonObject.get("ats");
            if(atsElem != null && !atsElem.isJsonNull()){
                result.put("ats", atsElem.getAsString());
            }
        }
        // Iterate over all entries to build the rest of the content map
        for(Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
            String key = entry.getKey();
            if("ats".equals(key)){
                continue; // already processed
            }
            JsonElement elem = entry.getValue();
            if(elem == null || elem.isJsonNull()){
                continue; // skip null values
            }
            if(elem.isJsonPrimitive()){
                JsonPrimitive prim = elem.getAsJsonPrimitive();
                if(prim.isString()){
                    result.put(key, prim.getAsString());
                } else if(prim.isNumber()){
                    result.put(key, prim.getAsNumber());
                } else if(prim.isBoolean()){
                    result.put(key, prim.getAsBoolean());
                } else {
                    result.put(key, prim.getAsString());
                }
            } else if(elem.isJsonArray()){
                result.put(key, elem.getAsJsonArray());
            } else if(elem.isJsonObject()){
                result.put(key, elem.getAsJsonObject());
            } else {
                result.put(key, elem);
            }
        }
    } catch(Exception e){
        // In case of any unexpected error, return what has been built so far
    }
    return result;
}

