public final byte[] toByteArray() {
    List<byte[]> bufList = this.buffers;
    if (bufList == null || bufList.isEmpty()) {
        return new byte[0];
    }
    long totalLong = 0;
    for (byte[] b : bufList) {
        if (b != null) {
            totalLong += b.length;
            if (totalLong > Integer.MAX_VALUE) {
                throw new IllegalStateException("Total buffer size exceeds maximum array length");
            }
        }
    }
    int total = (int) totalLong;
    byte[] result = new byte[total];
    int pos = 0;
    for (byte[] b : bufList) {
