            System.arraycopy(b, 0, result, pos, b.length);
            pos += b.length;
        }
    }
    return result;
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                sb.append('\\');
                i++;
                continue;
            }
            char next = str.charAt(i + 1);
            if (next == '\\') {
                sb.append('\\');
                i += 2;
                continue;
            }
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case '\"':
                    sb.append('\"');
                    i += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 2;
                    break;
                case 'u':
                    if (i + 6 > str.length()) {
                        throw new Exception("Invalid Unicode escape sequence at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i);
                    }
                    i += 6;
                    break;
                default:
                    sb.append(next);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

