final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    if (classFileBuffer == null) {
        throw new NullPointerException("classFileBuffer is null");
    }
    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= constantPoolCount) {
        throw new IllegalArgumentException("Invalid constant pool index");
    }
    int offset = 10; // after magic, minor_version, major_version, constant_pool_count
    for (int i = 1; i <= constantPoolEntryIndex; i++) {
        if (offset >= classFileBuffer.length) {
            throw new IllegalArgumentException("Constant pool index out of bounds");
        }
        int tag = classFileBuffer[offset] & 0xFF;
        if (i == constantPoolEntryIndex) {
            if (tag != 1) { // CONSTANT_Utf8
                throw new IllegalArgumentException("Entry is not CONSTANT_Utf8");
            }
            if (offset + 3 > classFileBuffer.length) {
                throw new IllegalArgumentException("Malformed constant pool entry");
            }
            int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
            if (offset + 3 + length > classFileBuffer.length) {
                throw new IllegalArgumentException("Invalid UTF8 length");
            }
            try {
                java.nio.charset.CharsetDecoder decoder = java.nio.charset.StandardCharsets.UTF_8.newDecoder();
                java.nio.ByteBuffer byteBuf = java.nio.ByteBuffer.wrap(classFileBuffer, offset + 3, length);
                java.nio.CharBuffer charBuf = java.nio.CharBuffer.wrap(charBuffer);
                decoder.decode(byteBuf, charBuf, true);
                decoder.flush(charBuf);
                int charsRead = charBuf.position();
                return new String(charBuffer, 0, charsRead);
            } catch (java.nio.charset.CharacterCodingException e) {
                throw new IllegalArgumentException("Invalid UTF-8 encoding", e);
            } catch (java.nio.BufferOverflowException e) {
                throw new IllegalArgumentException("charBuffer too small", e);
            }
        } else {
            // Skip over this entry
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    if (offset + 3 > classFileBuffer.length) {
                        throw new IllegalArgumentException("Malformed constant pool entry");
                    }
                    int len = ((classFileBuffer[offset + 1] & 0xFF) << 8) | (classFileBuffer[offset + 2] & 0xFF);
                    offset += 3 + len;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                case 15: // CONSTANT_MethodHandle
                case 16: // CONSTANT_MethodType
                case 18: // CONSTANT_InvokeDynamic
                    offset += 3;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 9;
                    i++; // these take up two entries
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                    offset += 3;
                    break;
                default:
                    throw new IllegalArgumentException("Unknown constant pool tag: " + tag);
            }
        }
    }
    throw new IllegalStateException("Unexpected end of constant pool traversal");
}

private static char decodeHexNibble(final char c){
    if (c >= '0' && c <= '9') {
