private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.getNode();

    // If the starting node already satisfies the predicate or is the stop node, return immediately
    if (predicate.test(current) || current.equals(stop)) {
        return circ;
    }

    // Use a set to detect loops and avoid infinite traversal
    java.util.Set<Node> visited = new java.util.HashSet<>();
    visited.add(current);

    while (true) {
        circ.next();
        current = circ.getNode();

        if (current.equals(stop) || predicate.test(current)) {
            return circ;
        }

        // If we revisit a node, break to avoid infinite loop
        if (!visited.add(current)) {
            return circ;
        }
    }
}

