public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength <= 0){
        return this;
    }
    if(byteLength < 0){
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if(byteOffset < 0){
        throw new IllegalArgumentException("byteOffset must be non-negative");
    }
    if(byteArrayValue != null){
        if(byteOffset + byteLength > byteArrayValue.length){
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds byteArrayValue length");
        }
    }
    int newSize = size + byteLength;
    if(newSize < 0){
        throw new OutOfMemoryError("ByteVector too large");
    }
    if(buffer == null){
        buffer = new byte[newSize];
    } else if(buffer.length < newSize){
        int newCapacity = buffer.length * 2;
        if(newCapacity < 0 || newCapacity < newSize){
            newCapacity = newSize;
        }
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, size);
        buffer = newBuffer;
    }
    if(byteArrayValue != null){
        System.arraycopy(byteArrayValue, byteOffset, buffer, size, byteLength);
    } else {
        for(int i = size; i < newSize; i++){
            buffer[i] = 0;
        }
    }
    size = newSize;
    return this;
}

