private void check(String modelName) throws IllegalStateException {
    if (modelName == null) {
        throw new IllegalStateException("Model name cannot be null");
    }
    java.util.List<java.lang.Integer> indices = SHARDING_KEY_INDICES.get(modelName);
    if (indices == null || indices.isEmpty()) {
        throw new IllegalStateException("No sharding key indices defined for model: " + modelName);
    }
    java.util.List<java.lang.Integer> sorted = new java.util.ArrayList<>(indices);
    java.util.Collections.sort(sorted);
    for (int i = 0; i < sorted.size(); i++) {
        java.lang.Integer idx = sorted.get(i);
        if (idx == null) {
            throw new IllegalStateException("Null sharding key index found for model: " + modelName);
        }
        if (i > 0 && sorted.get(i - 1) + 1 != idx) {
            throw new IllegalStateException("Sharding key indices for model " + modelName + " are not continuous");
        }
    }
}

public byte readByte() throws IOException {
    // Ensure the buffer and input stream are initialized
    if (buffer == null) {
        throw new IOException("Buffer is null");
    }
    if (in == null) {
        throw new IOException("Input stream is null");
    }
    if (buffer.length == 0) {
        throw new IOException("Buffer size is zero");
    }

    // Refill the buffer if all bytes have been consumed
    if (pos >= limit) {
        int bytesRead = in.read(buffer, 0, buffer.length);
        if (bytesRead == -1) {
            throw new IOException("End of stream reached");
        }
        if (bytesRead == 0) {
            // This should not happen unless the buffer length is zero
            throw new IOException("No data read into buffer");
        }
        pos = 0;
        limit = bytesRead;
    }

    // Return the next byte from the buffer
    return buffer[pos++];
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        throw new IllegalArgumentException("AtmosphereResource cannot be null");
    }
    try {
        AtmosphereResource.TRANSPORT transport = r.getTransport();
        if (transport != null) {
            switch (transport) {
                case LONG_POLLING:
                case SSE:
                case STREAMING:
                    r.suspend();
                    break;
                case WEBSOCKET:
                    // WebSocket connections are already suspended
                    break;
                default:
                    r.suspend();
                    break;
            }
        } else {
            r.suspend();
        }
    } catch (Exception e) {
        // ignore or log the exception
    }
    return Action.CONTINUE;
}

public int compare(Object aObj1,Object aObj2){
    // Handle nulls: null is considered less than any non-null value
    if (aObj1 == aObj2) return 0;          // covers both null
    if (aObj1 == null) return -1;
    if (aObj2 == null) return 1;

    // If both objects are Comparable and of the same runtime type, use compareTo
    if (aObj1 instanceof Comparable && aObj2 instanceof Comparable
        && aObj1.getClass() == aObj2.getClass()) {
        try {
            @SuppressWarnings("unchecked")
            Comparable<Object> comp = (Comparable<Object>) aObj1;
            return comp.compareTo(aObj2);
        } catch (ClassCastException e) {
            // Fall back to string comparison if compareTo fails
        }
    }

    // Fallback: compare string representations
    try {
        String s1 = aObj1.toString();
        String s2 = aObj2.toString();
        return s1.compareTo(s2);
    } catch (Exception e) {
        throw new IllegalArgumentException("Objects cannot be compared", e);
    }
}

public void removeAppender(String name) {
