    }
    synchronized (appenders) {
        java.util.Iterator<Appender> it = appenders.iterator();
        while (it.hasNext()) {
            Appender app = it.next();
            if (java.util.Objects.equals(name, app.getName())) {
                it.remove();
                return;
            }
        }
    }
}

public int appendLoopOnAppenders(LoggingEvent event) {
