    }
    int count = 0;
    Enumeration<Appender> appenders = this.getAllAppenders();
    if (appenders == null) {
        return 0;
    }
    while (appenders.hasMoreElements()) {
        Appender appender = appenders.nextElement();
        if (appender != null) {
            try {
                appender.doAppend(event);
                count++;
            } catch (Throwable t) {
                throw new RuntimeException("Error appending to appender: " + appender, t);
            }
        }
    }
    return count;
}

