        return new byte[0];
    }
    return result;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (tour == null) {
        throw new IllegalArgumentException("Tour set must not be null");
    }
    if (tour.isEmpty()) {
        return new org.jgrapht.graph.DefaultGraphPath<>(graph, null, null,
                java.util.Collections.emptyList(), java.util.Collections.emptyList(), 0.0);
    }
    // Validate that all edges belong to the graph
    for (E e : tour) {
        if (e == null) {
            throw new IllegalArgumentException("Edge in tour set is null");
        }
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not part of the graph");
        }
    }
    // Build adjacency map
    java.util.Map<V, java.util.List<E>> adjacency = new java.util.HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new java.util.ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new java.util.ArrayList<>()).add(e);
    }
    // Find a start vertex (prefer a vertex with degree 1)
    V start = null;
    for (java.util.Map.Entry<V, java.util.List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // No endpoint found (cycle or disconnected); pick any vertex
        start = adjacency.keySet().iterator().next();
    }
    java.util.List<V> vertexList = new java.util.ArrayList<>();
    java.util.List<E> edgeList = new java.util.ArrayList<>();
    java.util.Set<E> remaining = new java.util.HashSet<>(tour);
    V current = start;
    vertexList.add(current);
    while (!remaining.isEmpty()) {
        java.util.List<E> edges = adjacency.get(current);
        if (edges == null) {
            break;
        }
        E nextEdge = null;
        for (E e : edges) {
            if (remaining.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        edgeList.add(nextEdge);
        remaining.remove(nextEdge);
        V next = graph.getEdgeSource(nextEdge).equals(current)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        current = next;
        vertexList.add(current);
    }
    if (!remaining.isEmpty()) {
        throw new IllegalArgumentException("The provided edge set does not form a single connected path");
    }
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    V end = vertexList.isEmpty() ? null : vertexList.get(vertexList.size() - 1);
    return new org.jgrapht.graph.DefaultGraphPath<>(graph, start, end, vertexList, edgeList, weight);
}

