int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("name and descriptor must not be null");
    }
    if (constantPool == null) {
        throw new IllegalStateException("Constant pool is not initialized");
    }
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);
    for (int i = 0; i < constantPool.size(); i++) {
        Object entry = constantPool.get(i);
        if (entry instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo cnat = (ConstantNameAndTypeInfo) entry;
            if (cnat.getNameIndex() == nameIndex && cnat.getDescriptorIndex() == descriptorIndex) {
                return i + 1; // constant pool indices are 1-based
            }
        }
    }
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    constantPool.add(newEntry);
    return constantPool.size(); // 1-based index of the newly added entry
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new IllegalArgumentException("Trailing backslash in escape sequence");
            }
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'v':
                    sb.append('\u000B');
                    i++;
                    break;
                case '0':
                    sb.append('\0');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case 'x':
                    if (i + 3 >= len) {
                        throw new IllegalArgumentException("Incomplete \\x escape sequence");
                    }
                    String hex2 = input.substring(i + 2, i + 4);
                    try {
                        int val2 = Integer.parseInt(hex2, 16);
                        sb.append((char) val2);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex digits in \\x escape: " + hex2);
                    }
                    i += 3;
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new IllegalArgumentException("Incomplete \\u escape sequence");
                    }
                    String hex4 = input.substring(i + 2, i + 6);
                    try {
                        int val4 = Integer.parseInt(hex4, 16);
                        sb.append((char) val4);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex digits in \\u escape: " + hex4);
                    }
                    i += 5;
                    break;
                case 'U':
                    if (i + 9 >= len) {
                        throw new IllegalArgumentException("Incomplete \\U escape sequence");
                    }
                    String hex8 = input.substring(i + 2, i + 10);
                    try {
                        int val8 = Integer.parseInt(hex8, 16);
                        sb.append((char) val8);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid hex digits in \\U escape: " + hex8);
                    }
                    i += 9;
                    break;
                default:
                    // Unrecognized escape, keep the character literally
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

