public boolean isCompatible(DataTable dataset){
    if (dataset == null) {
        return false;
    }
    try {
        // Attempt to retrieve the bucket value from the dataset
        Object datasetBucket = null;
        try {
            datasetBucket = dataset.getClass().getMethod("getBucket").invoke(dataset);
        } catch (Exception e) {
            // If the method does not exist, the dataset is not compatible
            return false;
        }

        // Attempt to retrieve the bucket value from this instance
        Object thisBucket = null;
        try {
            thisBucket = this.getClass().getField("bucket").get(this);
        } catch (Exception e) {
            // If the field does not exist, try a getter method
            try {
                thisBucket = this.getClass().getMethod("getBucket").invoke(this);
            } catch (Exception ex) {
                // No bucket information available
                return false;
            }
        }

        if (datasetBucket == null) {
            return thisBucket == null;
        }
        return datasetBucket.equals(thisBucket);
    } catch (Exception e) {
        // Any unexpected exception results in incompatibility
        return false;
    }
}

