@Override
protected V provideNextVertex() {
    try {
        java.lang.reflect.Field field = null;
        for (String name : new String[]{"vertexIterator", "vertexQueue", "vertices"}) {
            try {
                field = this.getClass().getDeclaredField(name);
                field.setAccessible(true);
                break;
            } catch (NoSuchFieldException ignored) {}
        }
        if (field == null) {
            return null;
        }
        Object obj = field.get(this);
        if (obj instanceof java.util.Iterator) {
            java.util.Iterator<?> it = (java.util.Iterator<?>) obj;
            if (it.hasNext()) {
                return (V) it.next();
            }
        } else if (obj instanceof java.util.Queue) {
            java.util.Queue<?> q = (java.util.Queue<?>) obj;
            if (!q.isEmpty()) {
                return (V) q.poll();
            }
        } else if (obj instanceof java.util.List) {
            java.util.List<?> list = (java.util.List<?>) obj;
            if (!list.isEmpty()) {
                return (V) list.remove(0);
            }
        }
        return null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to provide next vertex", e);
    }
}

