void removeSelf() {
    // Unlink this bucket from its doubly linked list
    if (prev != null) {
        prev.next = next;
    } else if (parent != null) {
        // This bucket is the head of the list
        parent.head = next;
    }
    if (next != null) {
        next.prev = prev;
    }
    // Update parent size if applicable
    if (parent != null) {
        parent.size--;
    }
    // Clear references to help garbage collection
    prev = null;
    next = null;
}

