private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // Validate that the node is actually linked in this list
    if (node.prev != null && node.prev.next != node) {
        return false;
    }
    if (node.next != null && node.next.prev != node) {
        return false;
    }
    // Remove the node from the list
    if (node.prev != null) {
        node.prev.next = node.next;
    } else {
        head = node.next;
    }
    if (node.next != null) {
        node.next.prev = node.prev;
    } else {
        tail = node.prev;
    }
    // Clear the node's references
    node.prev = null;
    node.next = null;
    size--;
    return true;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> ranges = new ArrayList<>();
    try {
        if (currentProfiles == null) {
            return ranges;
        }
        for (Profile profile : currentProfiles) {
            if (profile == null) {
                continue;
            }
            List<SegmentSnapshot> snapshots = profile.getSegmentSnapshots();
            if (snapshots == null) {
                continue;
            }
            for (SegmentSnapshot snapshot : snapshots) {
                if (snapshot == null) {
                    continue;
                }
                long start = snapshot.getStart();
                long end = snapshot.getEnd();
                if (start <= end) {
                    ranges.add(new SequenceRange(start, end));
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return the ranges collected so far
    }
    return ranges;
}

