    int len = arr.length;
    if (from < 0 || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", length=" + len);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to do
    }
    // If the source list is empty, nothing to move
    if (list.head == null) {
        return;
    }

    // Detach the entire sublist from the source list
    ListNodeImpl<E> srcHead = list.head;
    ListNodeImpl<E> srcTail = list.tail;
    int movedSize = list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;

    // Attach the detached sublist to this list
    if (this.head == null) {
        // This list is empty; the detached sublist becomes the whole list
        this.head = srcHead;
        this.tail = srcTail;
        srcHead.prev = null;
    } else {
        // Append to the end of this list
        this.tail.next = srcHead;
        srcHead.prev = this.tail;
        this.tail = srcTail;
    }
    // Ensure the tail's next is null
    this.tail.next = null;

    // Update the size of this list
    this.size += movedSize;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
