    // If str is not null but prefix is null, no match
    if (prefix == null) {
        return false;
    }
    // If ignoreCase is true, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    // Otherwise use the standard startsWith
    return str.startsWith(prefix);
}

