    java.awt.Rectangle rect = table.getCellRect(row, 0, true);
    table.scrollRectToVisible(rect);
    // Delay repaint to allow the table to paint the newly selected row
    javax.swing.Timer timer = new javax.swing.Timer(50, e -> {
        table.repaint();
        ((javax.swing.Timer) e.getSource()).stop();
    });
    timer.setRepeats(false);
    timer.start();
}

public ByteVector putInt(final int intValue){
    // Ensure the internal buffer has enough space for 4 more bytes
    int required = pos + 4;
    if (buffer == null || buffer.length < required) {
        int newSize = Math.max(required, buffer == null ? 4 : buffer.length * 2);
        byte[] newBuffer = new byte[newSize];
        if (buffer != null) {
            System.arraycopy(buffer, 0, newBuffer, 0, pos);
        }
        buffer = newBuffer;
    }
    // Write the int in big-endian order
    buffer[pos++] = (byte) (intValue >> 24);
    buffer[pos++] = (byte) (intValue >> 16);
    buffer[pos++] = (byte) (intValue >> 8);
    buffer[pos++] = (byte) intValue;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    if (count < 0) {
        throw new IllegalArgumentException("count must be non-negative");
    }
    if (count == 0) {
        return true;
    }
    if (a == null || b == null) {
        return false;
    }
    if (count > a.length || count > b.length) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new NullPointerException("buf cannot be null");
    }
    if (name == null) {
        throw new IllegalStateException("name is null");
    }
    if (nameStart < 0 || nameStart > name.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    String sub = name.substring(nameStart);
    String trimmed = sub.trim();
    if (trimmed.isEmpty()) {
        return;
    }
    String[] parts = trimmed.split("\\s+");
    for (String part : parts) {
        if (!part.isEmpty()) {
            buf.append(part.charAt(0));
        }
    }
}

public static Type resolveBound(TypeVariable<?> typeVariable){
    try {
        if (typeVariable == null) {
            return Unknown.class;
        }
        Type[] bounds = typeVariable.getBounds();
        if (bounds == null || bounds.length == 0) {
            return Unknown.class;
        }
        Type bound = bounds[0];
        return bound != null ? bound : Unknown.class;
    } catch (Exception e) {
        return Unknown.class;
    }
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    java.util.List<Integer> result = new java.util.ArrayList<>(keys.size());
    java.util.List<Integer> ints = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("key cannot be null");
        }
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("key must be an Integer");
        }
        ints.add((Integer) key);
    }
    java.util.List<Integer> sorted = new java.util.ArrayList<>(ints);
    java.util.Collections.sort(sorted);
    for (Integer key : ints) {
        int idx = java.util.Collections.binarySearch(sorted, key);
        if (idx < 0) {
            result.add(java.lang.Integer.MIN_VALUE);
            continue;
        }
        while (idx > 0 && sorted.get(idx - 1).equals(key)) {
            idx--;
        }
        int lower = idx > 0 ? sorted.get(idx - 1) : java.lang.Integer.MIN_VALUE;
        result.add(lower);
    }
    return result;
}

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }
    // Void type does not consume a stack entry
    if (descriptor.equals("V")) {
        return;
    }
    // Method descriptor: pop argument types only
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String args = descriptor.substring(1, end);
        int i = 0;
        while (i < args.length()) {
            // Parse one type
            char c = args.charAt(i);
            // Handle array types
            while (c == '[') {
                i++;
                if (i >= args.length()) {
                    throw new IllegalArgumentException("Invalid array type in descriptor");
                }
                c = args.charAt(i);
            }
            if (c == 'L') {
                int semicolon = args.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid object type in descriptor");
                }
                i = semicolon + 1;
            } else {
                // Primitive type
                i++;
            }
            // Pop one stack entry for this argument type
            if (outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Stack underflow while popping argument types");
            }
            outputFrameStack.pop();
        }
    } else {
        // Single type descriptor
        int i = 0;
        char c = descriptor.charAt(i);
        // Handle array types
        while (c == '[') {
            i++;
            if (i >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid array type in descriptor");
            }
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid object type in descriptor");
            }
            i = semicolon + 1;
        } else {
            // Primitive type
            i++;
        }
        // Pop one stack entry for this type
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException("Stack underflow while popping type");
        }
        outputFrameStack.pop();
    }
}

