private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    int size = keys.size();
    List<Integer> result = new ArrayList<>(size);
    if (size == 0) {
        return result;
    }
    Map<K, Integer> lastIndexMap = new HashMap<>();
    for (int i = 0; i < size; i++) {
        K key = keys.get(i);
        lastIndexMap.put(key, i);
    }
    for (int i = 0; i < size; i++) {
        K key = keys.get(i);
        result.add(lastIndexMap.get(key));
    }
    return result;
}

public static String encodeTemplateNames(String s){
    if (s == null) {
        return null;
    }
    // Replace '{' with its percent-encoded form "%7B" and '}' with "%7D"
    // Using StringBuilder for efficiency if the string is large
    StringBuilder sb = new StringBuilder(s.length());
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '{') {
            sb.append("%7B");
        } else if (c == '}') {
            sb.append("%7D");
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static boolean equals(Point2D p1, Point2D p2) {
    // Handle null references
    if (p1 == null && p2 == null) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }

    final double tolerance = 1e-9;
    double dx = p1.getX() - p2.getX();
    double dy = p1.getY() - p2.getY();

    return Math.abs(dx) <= tolerance && Math.abs(dy) <= tolerance;
}

