public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    if (relativePath.isEmpty()) {
        return path;
    }

    boolean isAbsolute = path.startsWith("/");
    String[] pathParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();

    for (String part : pathParts) {
        if (!part.isEmpty()) {
            stack.add(part);
        }
    }

    // If the base path refers to a file (does not end with '/'), drop the last component
    if (!path.endsWith("/") && !stack.isEmpty()) {
        stack.remove(stack.size() - 1);
    }

    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!isAbsolute) {
                // Preserve leading '..' for relative bases that cannot go above root
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }

    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    if (result.length() == 0 && isAbsolute) {
        return "/";
    }
    return result.toString();
}

