static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }
    // If no nulls and array is already a String[], return it directly
    if (count == array.length && array instanceof String[]) {
        return (String[]) array;
    }
    String[] result = new String[count];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

