protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    if (clientWriters == null) {
        return;
    }
    synchronized (clientWriters) {
        java.util.Iterator<java.io.PrintWriter> it = clientWriters.iterator();
        while (it.hasNext()) {
            java.io.PrintWriter out = it.next();
            if (out == null) {
                it.remove();
                continue;
            }
            try {
                out.println(message);
                out.flush();
            } catch (Exception e) {
                it.remove();
                try {
                    out.close();
                } catch (Exception ex) {
                    // ignore
                }
            }
        }
    }
}

public static String toString(final char ch){
    // For ASCII 7-bit characters, return a cached String instance.
    // A static cache array is used to store String objects for characters 0-127.
    // If the character is outside this range, create a new String instance.
    // This implementation ensures that the same String object is returned for
    // each ASCII character, improving performance for repeated conversions.
    // The cache is initialized lazily on first use.
    if (ch < 128) {
        // Lazy initialization of the cache
        if (toStringCache == null) {
            synchronized (CharUtils.class) {
                if (toStringCache == null) {
                    toStringCache = new String[128];
                    for (int i = 0; i < 128; i++) {
                        toStringCache[i] = String.valueOf((char) i);
                    }
                }
            }
        }
        return toStringCache[ch];
    }
    return String.valueOf(ch);
}

