public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // EOF reached before a complete tag; return 0 as per protocol spec
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    // If we get here, the varint is too long to be a valid tag
    throw new IOException("Malformed varint");
}

