    return this;
}

private String buildContentRange(){
    try {
        Long start = null;
        Long end = null;
        Long total = null;
        java.lang.reflect.Field[] fields = getClass().getDeclaredFields();
        for (java.lang.reflect.Field f : fields) {
            f.setAccessible(true);
            Object val = f.get(this);
            if (!(val instanceof Number)) continue;
            String name = f.getName().toLowerCase();
            if (name.contains("start") && start == null) {
                start = ((Number) val).longValue();
            } else if (name.contains("end") && end == null) {
                end = ((Number) val).longValue();
            } else if ((name.contains("total") || name.contains("size") || name.contains("length")) && total == null) {
                total = ((Number) val).longValue();
            }
        }
        if (start == null || end == null || total == null) {
            return null;
        }
        return "bytes " + start + "-" + end + "/" + total;
    } catch (Exception e) {
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges must not be null");
    }
    List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.ObjectInputStream ois = new java.io.ObjectInputStream(new java.io.BufferedInputStream(new java.io.FileInputStream(file)))) {
        while (true) {
            try {
                Object obj = ois.readObject();
                if (!(obj instanceof ThreadSnapshot)) {
                    continue;
                }
                ThreadSnapshot snapshot = (ThreadSnapshot) obj;
                long ts;
                try {
                    ts = snapshot.getTimestamp();
                } catch (Exception e) {
                    // Skip snapshots that cannot provide a timestamp
                    continue;
                }
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (ts >= range.getStart() && ts <= range.getEnd()) {
                        result.add(snapshot);
                        break;
                    }
                }
            } catch (java.io.EOFException eof) {
                break; // End of file reached
            } catch (ClassNotFoundException cnf) {
                // Skip objects that cannot be deserialized
                continue;
            }
        }
    }
    return result;
}
